nf_u8 nf_derive_a(nf_u8 id,nf_u32 destination,nf_u32 auto_address,nf_u16 auto_size,nf_u32 config_address,nf_u16 config_size){nf_u16 i,c,available,required,free_slots;nf_u8 j,auto_found,config_found;if(check())return nf_error;if(!nf_inactive()||id>=3||!sources[id].valid||!range(destination,368640UL,0)||auto_address>capacity-auto_size||config_address>capacity-config_size)return fail(NF_E_INPUT);for(j=0;j<3;j++)if(sources[j].valid&&destination<sources[j].base+368640UL&&sources[j].base<destination+368640UL)return fail(NF_E_INPUT);if((destination<auto_address+auto_size&&auto_address<destination+368640UL)||(destination<config_address+config_size&&config_address<destination+368640UL))return fail(NF_E_INPUT);if(read_at(sources[id].base+2560UL,compare,64))return nf_error;if(memcmp(compare,"IO      SYS",11)||memcmp(compare+32,"MSDOS   SYS",11)||rd16(compare+26)!=2||fat12(id,2)!=3)return fail(NF_E_SOURCE);available=free_slots=0;auto_found=config_found=0;for(c=2;c<=355;c++){if(fat12(id,c)==0)available++;if(nf_error)return nf_error;}for(i=0;i<112;i++){if(read_at(sources[id].base+2560UL+(nf_u32)i*32UL,raw,32))return nf_error;if(!raw[0]){free_slots+=112U-i;break;}if(raw[0]==0xe5){free_slots++;continue;}if(!memcmp(raw,"AUTOEXECBAT",11)||!memcmp(raw,"CONFIG  SYS",11)){if(raw[0]=='A')auto_found=1;else config_found=1;available+=(nf_u16)((rd32(raw+28)+1023UL)/1024UL);}}required=(nf_u16)(((nf_u32)auto_size+1023UL)/1024UL+((nf_u32)config_size+1023UL)/1024UL);if(required>available||free_slots<(nf_u16)(2U-auto_found-config_found))return fail(NF_E_FULL);a_base=destination;for(i=0;i<720;i++){if(read_at(sources[id].base+(nf_u32)i*512UL,nf_sector,512)||a_write(destination+(nf_u32)i*512UL,nf_sector,512))return nf_error;}if(a_put("CONFIG  SYS",config_address,config_size)||a_put("AUTOEXECBAT",auto_address,auto_size))return nf_error;return 0;}

nf_u8 nf_ack_zero(nf_u32 actual,nf_u8 io_error){if(check())return nf_error;if(life!=4)return fail(NF_E_STATE);if(io_error||!actual||(actual&511UL)||actual>actual_total-actual_position)return fail(NF_E_IO);actual_position+=actual;life=actual_position==actual_total?5:2;progress();return 0;}

